from typing import List

class Solution:
    def countBowlSubarrays(self, nums: List[int]) -> int:
        # A bowl subarray has length >= 3 where nums[l] and nums[r] are strictly greater than all elements between them
        n = len(nums)
        ans = 0

        for l in range(n):
            for r in range(l + 2, n):
                boundary_min = min(nums[l], nums[r])
                # Check if all elements strictly between l and r are < boundary_min
                is_bowl = True
                for i in range(l + 1, r):
                    if nums[i] >= boundary_min:
                        is_bowl = False
                        break
                if is_bowl:
                    ans += 1

        return ans
