#include <vector>
#include <algorithm>

class Solution {
public:
    long long countBowlSubarrays(std::vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;

        for (int l = 0; l < n; ++l) {
            for (int r = l + 2; r < n; ++r) {
                int boundary = std::min(nums[l], nums[r]);
                bool valid = true;
                for (int i = l + 1; i < r; ++i) {
                    if (nums[i] >= boundary) {
                        valid = false;
                        break;
                    }
                }
                if (valid) ans++;
            }
        }
        return ans;
    }
};

class Solution {
    public long countBowlSubarrays(int[] nums) {
        int n = nums.length;
        long ans = 0;

        for (int l = 0; l < n; l++) {
            for (int r = l + 2; r < n; r++) {
                int boundary = Math.min(nums[l], nums[r]);
                boolean valid = true;
                for (int i = l + 1; i < r; i++) {
                    if (nums[i] >= boundary) {
                        valid = false;
                        break;
                    }
                }
                if (valid) ans++;
            }
        }
        return ans;
    }
}

